	long result = 1;
	long x = a;
	do {
	    if (x != (int) x) throw Utility.makeFortressException("fortress.CompilerBuiltin$IntegerOverflow");
	    if ((b & 1) != 0) {
		result *= x;
		if (result != (int) result) throw Utility.makeFortressException("fortress.CompilerBuiltin$IntegerOverflow");
	    }
	    b >>= 1;
	    x *= x;
	} while (b > 0);
	return (int) result;
    }

